//! The test corpus, generated by Rust code into
//! `target\corpus` — never kept in git.
//!
//! *A PowerShell script that generated these files was blocked and deleted
//! by the antivirus (2026-10-07), so the tests produce their own files, in
//! one language.*
//!
//! Every file is made lazily, the first time a test asks for it, and only once
//! per test process; files derived by QPDF (encrypted ones) need a QPDF build
//! in `bin\`. The PDFs are written byte by byte: small, readable in a text
//! editor, and with known content — page N of [`Item::Base`] shows "Page N", so
//! page order can be checked after merging.

use std::collections::HashSet;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

use super::{project_dir, qpdf};

/// One file of the corpus.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Item {
    /// 3 pages ("Page 1".."Page 3"), bookmarks, page labels i, ii, 1, and one
    /// text form field on page 1.
    Base,
    /// [`Item::Base`] with embedded files under hostile names
    /// ([`HOSTILE_ATTACHMENT_NAMES`]).
    Attachments,
    /// 10 000 pages sharing one content stream.
    Pages10k,
    /// About 100 MB of page content: a rewrite with recompression takes
    /// seconds, long enough to cancel in the middle.
    Heavy,
    /// [`Item::Base`] with a wrong `startxref`: QPDF repairs it, exit code 3.
    Damaged,
    /// [`Item::Base`] cut inside its first object (the catalog): beyond repair,
    /// exit code 2. (Cut in half, QPDF still rebuilds it from the surviving
    /// objects and only warns — measured.)
    Truncated,
    /// Plain text with a `.pdf` extension.
    NotPdf,
    /// A 0-byte `.pdf`.
    Empty,
    /// The QPDF manual (178 pages), copied from the msvc64 build.
    Manual,
    /// AES-256, open password [`USER_PASSWORD`], owner [`OWNER_PASSWORD`].
    EncryptedOpen,
    /// AES-256 with only an owner password: opens freely, printing forbidden.
    EncryptedOwnerOnly,
    /// RC4 40-bit (weak), open password [`USER_PASSWORD`].
    EncryptedRc4,
    /// [`Item::Base`] named `-x.pdf` — an option, if passed as a relative path.
    DashName,
    /// [`Item::Base`] named `@x.pdf` — an argument file, likewise.
    AtName,
    /// [`Item::Base`] with Polish letters and CJK in the name.
    UnicodeName,
    /// [`Item::Base`] at a path of 300 characters (beyond QPDF).
    LongPath,
    /// One page with an uncompressed 512×512 photo-like image (JPEG shrinks
    /// it a lot), document info ([`PHOTO_AUTHOR`]) and an XMP packet.
    Photo,
    /// [`Item::Photo`] with a 100×100 image: narrower and lower than QPDF's
    /// smallest image to re-encode (128×128), and of fewer pixels (16 384).
    SmallPhoto,
}

/// The author named in [`Item::Photo`]'s document info and XMP.
pub const PHOTO_AUTHOR: &str = "Jan Kowalski";

/// Open password of the encrypted items: spaces, Polish letters, a `=`.
pub const USER_PASSWORD: &str = "zażółć gęślą = jaźń";
pub const OWNER_PASSWORD: &str = "owner secret";

/// Attachment names a hostile PDF could carry.
pub const HOSTILE_ATTACHMENT_NAMES: &[&str] = &[
    r"..\..\outside.txt",
    "../../outside2.txt",
    r"C:\Windows\evil.txt",
    "CON",
    "nul.txt",
    "a:b.txt",
    "trailing dot. ",
    "zażółć.txt",
    // Shows as `invoiceexe.txt`: the right-to-left mark turns the rest around.
    "invoice\u{202E}txt.exe",
];

/// The long attachment name (300 characters) — kept apart, it is not readable
/// in a test failure message.
pub fn long_attachment_name() -> String {
    format!("{}.txt", "n".repeat(296))
}

/// Folder holding the generated files.
pub fn dir() -> PathBuf {
    project_dir().join("target").join("corpus")
}

/// Path of `item`, generated if need be: a test without it cannot run.
pub fn item(item: Item) -> PathBuf {
    get(item).expect("corpus item")
}

/// Path of `item`, generating it first if this process has not done so yet.
/// `None` when it needs QPDF and there is none in `bin\`.
pub fn get(item: Item) -> Option<PathBuf> {
    static MADE: Mutex<Option<HashSet<Item>>> = Mutex::new(None);
    let mut made = MADE.lock().unwrap_or_else(|e| e.into_inner());
    let path = path_of(item);
    if made.get_or_insert_with(HashSet::new).contains(&item) {
        return Some(path);
    }
    std::fs::create_dir_all(path.parent()?).expect("create corpus folder");
    let bytes = match item {
        Item::Base => base(false),
        Item::Attachments => base(true),
        Item::Pages10k => many_pages(10_000),
        Item::Heavy => heavy(),
        Item::Damaged => damaged(),
        Item::Truncated => {
            let full = base(false);
            full[..60].to_vec()
        }
        Item::NotPdf => b"This is a plain text file, not a PDF.\r\n".to_vec(),
        Item::Empty => Vec::new(),
        Item::Manual => std::fs::read(
            project_dir().join(r"bin\qpdf-12.4.2-msvc64\share\doc\qpdf\qpdf-manual.pdf"),
        )
        .ok()?,
        Item::DashName | Item::AtName | Item::UnicodeName | Item::LongPath => base(false),
        Item::Photo => photo(512),
        Item::SmallPhoto => photo(100),
        Item::EncryptedOpen | Item::EncryptedOwnerOnly | Item::EncryptedRc4 => {
            encrypt(item, &path)?;
            made.as_mut()?.insert(item);
            return Some(path);
        }
    };
    write(&path, &bytes);
    made.as_mut()?.insert(item);
    Some(path)
}

fn path_of(item: Item) -> PathBuf {
    let name = match item {
        Item::Base => "base.pdf",
        Item::Attachments => "attachments.pdf",
        Item::Pages10k => "pages-10000.pdf",
        Item::Heavy => "heavy.pdf",
        Item::Damaged => "damaged.pdf",
        Item::Truncated => "truncated.pdf",
        Item::NotPdf => "not-a-pdf.pdf",
        Item::Empty => "empty.pdf",
        Item::Manual => "qpdf-manual.pdf",
        Item::EncryptedOpen => "encrypted-open.pdf",
        Item::EncryptedOwnerOnly => "encrypted-owner-only.pdf",
        Item::EncryptedRc4 => "encrypted-rc4.pdf",
        Item::DashName => "-x.pdf",
        Item::AtName => "@x.pdf",
        Item::UnicodeName => "zażółć 文件.pdf",
        Item::Photo => "photo.pdf",
        Item::SmallPhoto => "small-photo.pdf",
        Item::LongPath => {
            // 4 nested folders of 60 characters, then the file: > 300 in total.
            let mut path = dir().join("long");
            for c in ['a', 'b', 'c', 'd'] {
                path.push(c.to_string().repeat(60));
            }
            return path.join("long-path.pdf");
        }
    };
    dir().join(name)
}

/// Write via a temporary name, so an interrupted run never leaves a half file
/// that a later run would trust.
fn write(path: &Path, bytes: &[u8]) {
    let part = path.with_extension("part");
    std::fs::write(&part, bytes).expect("write corpus file");
    std::fs::rename(&part, path).expect("finish corpus file");
}

/// Derive an encrypted file from [`Item::Base`] with the real QPDF.
fn encrypt(item: Item, path: &Path) -> Option<()> {
    let qpdf = qpdf()?;
    // `get` holds the lock, so the base is made inline instead of recursively.
    let base_path = dir().join("base-for-encryption.pdf");
    write(&base_path, &base(false));
    let mut args: Vec<String> = Vec::new();
    match item {
        Item::EncryptedOpen => args.extend([
            "--encrypt".into(),
            format!("--user-password={USER_PASSWORD}"),
            format!("--owner-password={OWNER_PASSWORD}"),
            "--bits=256".into(),
        ]),
        Item::EncryptedOwnerOnly => args.extend([
            "--encrypt".into(),
            "--user-password=".into(),
            format!("--owner-password={OWNER_PASSWORD}"),
            "--bits=256".into(),
            "--print=none".into(),
        ]),
        _ => args.extend([
            "--allow-weak-crypto".into(),
            "--encrypt".into(),
            format!("--user-password={USER_PASSWORD}"),
            format!("--owner-password={OWNER_PASSWORD}"),
            "--bits=40".into(),
        ]),
    }
    args.push("--".into());
    let part = path.with_extension("part");
    let status = std::process::Command::new(qpdf)
        .args(&args)
        .arg(&base_path)
        .arg(&part)
        .status()
        .expect("run qpdf");
    assert_eq!(status.code(), Some(0), "qpdf failed to make {item:?}");
    std::fs::rename(&part, path).expect("finish corpus file");
    Some(())
}

/// A minimal PDF writer: numbered objects, then the cross-reference table.
#[derive(Default)]
struct Pdf {
    objects: Vec<Vec<u8>>,
    /// The document info dictionary, if any.
    info: Option<usize>,
}

impl Pdf {
    /// Reserve the next object number (filled in later with [`Pdf::set`]).
    fn reserve(&mut self) -> usize {
        self.objects.push(Vec::new());
        self.objects.len()
    }

    fn set(&mut self, number: usize, body: impl Into<Vec<u8>>) {
        self.objects[number - 1] = body.into();
    }

    fn add(&mut self, body: impl Into<Vec<u8>>) -> usize {
        let number = self.reserve();
        self.set(number, body);
        number
    }

    fn add_stream(&mut self, dict: &str, data: &[u8]) -> usize {
        let mut body = format!("<< {dict} /Length {} >>\nstream\n", data.len()).into_bytes();
        body.extend_from_slice(data);
        body.extend_from_slice(b"\nendstream");
        self.add(body)
    }

    /// The finished file; `xref_shift` moves the `startxref` value (damage).
    fn finish(&self, root: usize, xref_shift: usize) -> Vec<u8> {
        let mut out = b"%PDF-1.7\n%\xe2\xe3\xcf\xd3\n".to_vec();
        let mut offsets = Vec::with_capacity(self.objects.len());
        for (i, body) in self.objects.iter().enumerate() {
            offsets.push(out.len());
            out.extend_from_slice(format!("{} 0 obj\n", i + 1).as_bytes());
            out.extend_from_slice(body);
            out.extend_from_slice(b"\nendobj\n");
        }
        let xref = out.len();
        out.extend_from_slice(format!("xref\n0 {}\n0000000000 65535 f \n", offsets.len() + 1).as_bytes());
        for offset in offsets {
            out.extend_from_slice(format!("{offset:010} 00000 n \n").as_bytes());
        }
        let info = self.info.map(|info| format!(" /Info {info} 0 R")).unwrap_or_default();
        out.extend_from_slice(
            format!(
                "trailer\n<< /Size {} /Root {root} 0 R{info} >>\nstartxref\n{}\n%%EOF\n",
                self.objects.len() + 1,
                xref + xref_shift
            )
            .as_bytes(),
        );
        out
    }
}

/// A PDF hex string; text as UTF-16BE with a byte order mark when `unicode`.
fn hex_string(text: &str, unicode: bool) -> String {
    let bytes: Vec<u8> = if unicode {
        [0xFE, 0xFF].into_iter().chain(text.encode_utf16().flat_map(u16::to_be_bytes)).collect()
    } else {
        text.bytes().collect()
    };
    let hex: String = bytes.iter().map(|b| format!("{b:02X}")).collect();
    format!("<{hex}>")
}

fn base(with_attachments: bool) -> Vec<u8> {
    base_pdf(with_attachments, 0)
}

fn damaged() -> Vec<u8> {
    base_pdf(false, 7)
}

fn base_pdf(with_attachments: bool, xref_shift: usize) -> Vec<u8> {
    let mut pdf = Pdf::default();
    let catalog = pdf.reserve();
    let pages = pdf.reserve();
    let font = pdf.add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");
    let field = pdf.reserve();
    let mut page_ids = Vec::new();
    for n in 1..=3 {
        let content = format!("BT /F1 36 Tf 72 700 Td (Page {n}) Tj ET");
        let content = pdf.add_stream("", content.as_bytes());
        let annots = if n == 1 { format!(" /Annots [{field} 0 R]") } else { String::new() };
        page_ids.push(pdf.add(format!(
            "<< /Type /Page /Parent {pages} 0 R /MediaBox [0 0 612 792] \
             /Resources << /Font << /F1 {font} 0 R >> >> /Contents {content} 0 R{annots} >>"
        )));
    }
    let kids: Vec<String> = page_ids.iter().map(|id| format!("{id} 0 R")).collect();
    pdf.set(pages, format!("<< /Type /Pages /Kids [{}] /Count 3 >>", kids.join(" ")));
    pdf.set(
        field,
        format!(
            "<< /Type /Annot /Subtype /Widget /FT /Tx /T (name) /V (hello) /F 4 \
             /Rect [72 600 300 630] /P {} 0 R /DA (/Helv 12 Tf 0 g) >>",
            page_ids[0]
        ),
    );
    // Bookmarks: one per page.
    let outlines = pdf.reserve();
    let items: Vec<usize> = (0..3).map(|_| pdf.reserve()).collect();
    for (i, &item) in items.iter().enumerate() {
        let mut dict = format!(
            "<< /Title (Bookmark {}) /Parent {outlines} 0 R /Dest [{} 0 R /Fit]",
            i + 1,
            page_ids[i]
        );
        if i > 0 {
            dict.push_str(&format!(" /Prev {} 0 R", items[i - 1]));
        }
        if i + 1 < items.len() {
            dict.push_str(&format!(" /Next {} 0 R", items[i + 1]));
        }
        dict.push_str(" >>");
        pdf.set(item, dict);
    }
    pdf.set(
        outlines,
        format!("<< /Type /Outlines /First {} 0 R /Last {} 0 R /Count 3 >>", items[0], items[2]),
    );
    let names = if with_attachments {
        let mut entries = Vec::new();
        let long = long_attachment_name();
        let all = HOSTILE_ATTACHMENT_NAMES.iter().copied().chain([long.as_str()]);
        for (i, name) in all.enumerate() {
            let body = format!("attachment {i}: {name}\r\n");
            let file = pdf.add_stream("/Type /EmbeddedFile", body.as_bytes());
            let spec = pdf.add(format!(
                "<< /Type /Filespec /F {} /UF {} /EF << /F {file} 0 R >> >>",
                hex_string(name, false),
                hex_string(name, true)
            ));
            // Name-tree keys must be sorted and unique: a numbered key.
            entries.push(format!("(a{i:02}) {spec} 0 R"));
        }
        format!(" /Names << /EmbeddedFiles << /Names [{}] >> >>", entries.join(" "))
    } else {
        String::new()
    };
    pdf.set(
        catalog,
        format!(
            "<< /Type /Catalog /Pages {pages} 0 R /Outlines {outlines} 0 R \
             /PageLabels << /Nums [0 << /S /r >> 2 << /S /D >>] >> \
             /AcroForm << /Fields [{field} 0 R] /DA (/Helv 12 Tf 0 g) /NeedAppearances true >>{names} >>"
        ),
    );
    pdf.finish(catalog, xref_shift)
}

/// `count` pages, all drawing the same content stream.
fn many_pages(count: usize) -> Vec<u8> {
    let mut pdf = Pdf::default();
    let catalog = pdf.reserve();
    let pages = pdf.reserve();
    let font = pdf.add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");
    let content = pdf.add_stream("", b"BT /F1 36 Tf 72 700 Td (Same page) Tj ET");
    let kids: Vec<String> = (0..count)
        .map(|_| {
            let page = pdf.add(format!(
                "<< /Type /Page /Parent {pages} 0 R /MediaBox [0 0 612 792] \
                 /Resources << /Font << /F1 {font} 0 R >> >> /Contents {content} 0 R >>"
            ));
            format!("{page} 0 R")
        })
        .collect();
    pdf.set(pages, format!("<< /Type /Pages /Kids [{}] /Count {count} >>", kids.join(" ")));
    pdf.set(catalog, format!("<< /Type /Catalog /Pages {pages} 0 R >>"));
    pdf.finish(catalog, 0)
}

/// 400 pages, each with ~256 KB of uncompressed text-drawing operators.
fn heavy() -> Vec<u8> {
    let mut pdf = Pdf::default();
    let catalog = pdf.reserve();
    let pages = pdf.reserve();
    let font = pdf.add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");
    let mut kids = Vec::new();
    let mut seed = 12_345u32;
    for _ in 0..400 {
        let mut content = String::with_capacity(270_000);
        content.push_str("BT /F1 6 Tf 20 780 Td 7 TL\n");
        while content.len() < 256 * 1024 {
            // Text varied enough that compression has real work to do.
            let line = next(&mut seed);
            content.push_str(&format!("(Line {line:010} of heavy content) '\n"));
        }
        content.push_str("ET");
        let content = pdf.add_stream("", content.as_bytes());
        let page = pdf.add(format!(
            "<< /Type /Page /Parent {pages} 0 R /MediaBox [0 0 612 792] \
             /Resources << /Font << /F1 {font} 0 R >> >> /Contents {content} 0 R >>"
        ));
        kids.push(format!("{page} 0 R"));
    }
    pdf.set(pages, format!("<< /Type /Pages /Kids [{}] /Count {} >>", kids.join(" "), kids.len()));
    pdf.set(catalog, format!("<< /Type /Catalog /Pages {pages} 0 R >>"));
    pdf.finish(catalog, 0)
}

/// One page showing a `side`×`side` RGB image stored without compression —
/// smooth colours with a little grain, which JPEG takes far better than
/// Flate — plus document info and XMP naming [`PHOTO_AUTHOR`].
fn photo(side: usize) -> Vec<u8> {
    let mut pdf = Pdf::default();
    let catalog = pdf.reserve();
    let pages = pdf.reserve();
    let mut pixels = Vec::with_capacity(side * side * 3);
    let mut seed = 7u32;
    for y in 0..side {
        for x in 0..side {
            let grain = (next(&mut seed) >> 28) as usize; // 0..16
            pixels.push(((x / 2 + grain) % 256) as u8);
            pixels.push(((y / 2 + grain) % 256) as u8);
            pixels.push((((x + y) / 4 + grain) % 256) as u8);
        }
    }
    let image = pdf.add_stream(
        &format!("/Type /XObject /Subtype /Image /Width {side} /Height {side} /ColorSpace /DeviceRGB /BitsPerComponent 8"),
        &pixels,
    );
    let content = pdf.add_stream("", b"q 512 0 0 512 50 200 cm /Im1 Do Q");
    let page = pdf.add(format!(
        "<< /Type /Page /Parent {pages} 0 R /MediaBox [0 0 612 792] \
         /Resources << /XObject << /Im1 {image} 0 R >> >> /Contents {content} 0 R >>"
    ));
    pdf.set(pages, format!("<< /Type /Pages /Kids [{page} 0 R] /Count 1 >>"));
    let xmp = format!(
        "<?xpacket begin=\"\" id=\"W5M0MpCehiHzreSzNTczkc9d\"?>\n\
         <x:xmpmeta xmlns:x=\"adobe:ns:meta/\"><rdf:RDF xmlns:rdf=\"http://www.w3.org/1999/02/22-rdf-syntax-ns#\">\
         <rdf:Description rdf:about=\"\" xmlns:dc=\"http://purl.org/dc/elements/1.1/\">\
         <dc:creator><rdf:Seq><rdf:li>{PHOTO_AUTHOR}</rdf:li></rdf:Seq></dc:creator>\
         </rdf:Description></rdf:RDF></x:xmpmeta>\n<?xpacket end=\"w\"?>"
    );
    let metadata = pdf.add_stream("/Type /Metadata /Subtype /XML", xmp.as_bytes());
    pdf.info = Some(pdf.add(format!("<< /Title (Holiday photo) /Author ({PHOTO_AUTHOR}) /Producer (QpdfDesk tests) >>")));
    pdf.set(catalog, format!("<< /Type /Catalog /Pages {pages} 0 R /Metadata {metadata} 0 R >>"));
    pdf.finish(catalog, 0)
}

/// A cheap deterministic generator: varied content, the same every run.
fn next(seed: &mut u32) -> u32 {
    *seed = seed.wrapping_mul(1_103_515_245).wrapping_add(12_345);
    *seed
}
